"""Kaggle kernel for the grad-refactor-ai lane (generated by training/kaggle/lane.py).

lane.py replaces the JOB line below with the job description and pushes this file as a
private script kernel. On Kaggle it:

1. records the hardware (GPU model, driver, compute capability, CPU, RAM) and Python;
2. finds the private bundle dataset (extracted tree or bundle.zip), copies it to /tmp
   and verifies every file against bundle-manifest.json;
3. installs the pinned transformers/peft/accelerate/safetensors/tokenizers/
   huggingface-hub versions from training/requirements-cuda.txt and the core pydantic
   pin, keeping Kaggle's own torch (a constraint file stops pip from changing it);
4. downloads Qwen/Qwen2.5-Coder-0.5B-Instruct at the pinned revision and verifies the
   SHA-256 of model.safetensors;
5. runs one job: "train" (training/train_lora.py with configs/training.full.json),
   "eval" (scripts/evaluate.py on the job's split, then report_evaluation.py) or
   "smoke" (the same evaluation on a few validation cases);
6. writes logs, hardware.json, status.json and outputs-manifest.json (SHA-256 of every
   output file) to /kaggle/working, and exits non-zero when a step failed.

Evaluation jobs use the validation split unless the job names the test split; a test job
needs a frozen protocol version, an explicit confirmation and a bundle built from a clean
commit, and scripts/evaluate.py applies its own frozen-test guard on top.
"""

import hashlib
import json
import os
import platform
import shutil
import subprocess
import sys
import time
import traceback
import zipfile
from datetime import UTC, datetime
from pathlib import Path

JOB = {}  # replaced by lane.py

SPLITS = ("validation", "test")  # test only for the single frozen-protocol final run
MODEL_ID = "Qwen/Qwen2.5-Coder-0.5B-Instruct"
MODEL_REVISION = "ea3f2471cf1b1f0db85067f1ef93848e38e88c25"
MODEL_SHA256 = "f9523886352217ded3aeeef552b381af79d568c6d49a4b9e423288cea56b0a44"
PINNED = (
    "transformers",
    "peft",
    "accelerate",
    "safetensors",
    "tokenizers",
    "huggingface-hub",
)
CORE_PINS = ("pydantic==2.14.1",)
WORK = Path("/kaggle/working")
TMP = Path("/tmp/grad")
REPO = TMP / "repo"
MODEL_DIR = TMP / "models" / "Qwen2.5-Coder-0.5B-Instruct"
LOGS = WORK / "logs"
STATUS = {"job": JOB, "started_at": datetime.now(UTC).isoformat(timespec="seconds"), "steps": []}


def log(message: str) -> None:
    line = f"[{datetime.now(UTC):%H:%M:%S}] {message}"
    print(line, flush=True)
    with open(LOGS / "kernel.log", "a", encoding="utf-8") as handle:
        handle.write(line + "\n")


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def run(command: list[str], name: str, cwd: Path | None = None, env: dict | None = None) -> int:
    """Run a command, logging its output to logs/<name>.log; returns the exit code."""
    log(f"$ {' '.join(command)}")
    started = time.time()
    with open(LOGS / f"{name}.log", "w", encoding="utf-8") as handle:
        process = subprocess.run(
            command, cwd=cwd, env=env, stdout=handle, stderr=subprocess.STDOUT, text=True
        )
    log(f"{name}: exit {process.returncode} after {time.time() - started:.1f} s")
    if process.returncode != 0:
        tail = (LOGS / f"{name}.log").read_text(encoding="utf-8", errors="replace")[-3000:]
        log(f"{name} log tail:\n{tail}")
    return process.returncode


class Step:
    def __init__(self, name: str) -> None:
        self.name = name

    def __enter__(self):
        self.started = time.time()
        log(f"== {self.name}")
        return self

    def __exit__(self, kind, value, tb):
        entry = {
            "step": self.name,
            "seconds": round(time.time() - self.started, 1),
            "ok": kind is None,
        }
        if kind is not None:
            entry["error"] = f"{kind.__name__}: {value}"[:2000]
            log("".join(traceback.format_exception(kind, value, tb))[-3000:])
        STATUS["steps"].append(entry)
        return False


def hardware() -> dict:
    info = {
        "python": sys.version.split()[0],
        "platform": platform.platform(),
        "cpu_count": os.cpu_count(),
    }
    try:
        meminfo = Path("/proc/meminfo").read_text().splitlines()
        info["ram_total_kb"] = int(meminfo[0].split()[1])
    except (OSError, IndexError, ValueError):
        info["ram_total_kb"] = None
    smi = subprocess.run(
        [
            "nvidia-smi",
            "--query-gpu=name,memory.total,driver_version,compute_cap",
            "--format=csv,noheader",
        ],
        capture_output=True,
        text=True,
    )
    info["nvidia_smi"] = smi.stdout.strip()
    probe = subprocess.run(
        [
            sys.executable,
            "-c",
            "import json, torch; print(json.dumps({'torch': torch.__version__, "
            "'cuda': torch.version.cuda, 'device': torch.cuda.get_device_name(0), "
            "'capability': list(torch.cuda.get_device_capability(0))}))",
        ],
        capture_output=True,
        text=True,
    )
    info["torch"] = json.loads(probe.stdout) if probe.returncode == 0 else probe.stderr[-500:]
    return info


def locate_bundle() -> None:
    manifests = sorted(Path("/kaggle/input").rglob("bundle-manifest.json"))
    zips = sorted(Path("/kaggle/input").rglob("bundle.zip"))
    if REPO.exists():
        shutil.rmtree(REPO)
    if manifests:
        source = manifests[0].parent
        shutil.copytree(source, REPO)
        log(f"bundle tree at {source}")
    elif zips:
        REPO.mkdir(parents=True)
        with zipfile.ZipFile(zips[0]) as archive:
            archive.extractall(REPO)
        log(f"bundle zip at {zips[0]}")
    else:
        raise FileNotFoundError("no bundle-manifest.json or bundle.zip under /kaggle/input")
    manifest = json.loads((REPO / "bundle-manifest.json").read_text(encoding="utf-8"))
    bad = [p for p, sha in manifest["files"].items() if sha256_file(REPO / p) != sha]
    if bad:
        raise ValueError(f"bundle files do not match the manifest: {bad[:10]}")
    if manifest["bundle_sha256"] != JOB["bundle_sha256"]:
        raise ValueError(
            f"bundle {manifest['bundle_sha256']} is not the one the job expects "
            f"({JOB['bundle_sha256']}); the dataset version is stale"
        )
    STATUS["bundle"] = {k: manifest[k] for k in ("bundle_sha256", "git_head", "git_dirty")}
    STATUS["bundle"]["files_verified"] = len(manifest["files"])


def install() -> None:
    lock = (REPO / "training" / "requirements-cuda.txt").read_text(encoding="utf-8")
    pins = [
        line.strip()
        for line in lock.splitlines()
        if line.strip() and not line.startswith("#") and line.split("==")[0] in PINNED
    ]
    if len(pins) != len(PINNED):
        raise ValueError(f"missing pins in the lock: {pins}")
    import torch

    constraints = TMP / "constraints.txt"
    constraints.write_text(f"torch=={torch.__version__}\n", encoding="utf-8")
    code = run(
        [
            sys.executable,
            "-m",
            "pip",
            "install",
            "--quiet",
            "-c",
            str(constraints),
            *pins,
            *CORE_PINS,
        ],
        "pip-install",
    )
    if code != 0:
        raise RuntimeError("pip install failed")
    # Kaggle's image ships torchao 0.10, and peft 0.21 raises ImportError while creating
    # LoRA layers whenever an older torchao is installed. The project does not use torchao.
    code = run(
        [sys.executable, "-m", "pip", "uninstall", "--yes", "--quiet", "torchao"],
        "pip-uninstall-torchao",
    )
    if code != 0:
        raise RuntimeError("pip uninstall torchao failed")
    STATUS["removed_packages"] = ["torchao"]
    check = subprocess.run(
        [
            sys.executable,
            "-I",
            "-c",
            "import json, importlib.metadata as m; print(json.dumps({n: m.version(n) for n in "
            + repr(list(PINNED) + ["pydantic", "torch"])
            + "}))",
        ],
        capture_output=True,
        text=True,
    )
    versions = json.loads(check.stdout)
    STATUS["packages_isolated_interpreter"] = versions
    wanted = {p.split("==")[0]: p.split("==")[1] for p in pins + list(CORE_PINS)}
    wrong = {n: (versions.get(n), v) for n, v in wanted.items() if versions.get(n) != v}
    if wrong:
        raise RuntimeError(f"installed versions differ from the pins (seen by python -I): {wrong}")
    run([sys.executable, "-m", "pip", "freeze"], "pip-freeze")


def download_model() -> None:
    os.environ["HF_HUB_DISABLE_XET"] = "1"
    from huggingface_hub import snapshot_download

    snapshot_download(MODEL_ID, revision=MODEL_REVISION, local_dir=MODEL_DIR)
    digest = sha256_file(MODEL_DIR / "model.safetensors")
    if digest != MODEL_SHA256:
        raise ValueError(f"model.safetensors sha256 {digest} != {MODEL_SHA256}")
    STATUS["model"] = {"model_id": MODEL_ID, "revision": MODEL_REVISION, "sha256": digest}


def precision() -> tuple[str, str]:
    """(training precision, inference dtype): fp32 unless the GPU has native bf16."""
    capability = STATUS["hardware"]["torch"]["capability"]
    return ("bf16", "bfloat16") if capability[0] >= 8 else ("fp32", "float32")


def train() -> None:
    training_precision, _ = precision()
    config = json.loads((REPO / "configs" / "training.full.json").read_text(encoding="utf-8"))
    run_id = JOB["run_id"]
    out = WORK / "training" / run_id
    config.update(
        model_path=str(MODEL_DIR),
        dataset=str(REPO / "datasets" / "guard_clauses" / "v1" / "records.jsonl"),
        output_dir=str(out),
        run_id=run_id,
        precision=training_precision,
        # The laptop's 55-minute cap does not apply here; the kernel's own session
        # limit (lane.py push --timeout-min) bounds the job on Kaggle.
        max_runtime_minutes=200,
    )
    path = TMP / "training.kaggle.json"
    path.write_text(json.dumps(config, indent=2), encoding="utf-8")
    shutil.copy(path, LOGS / "training.kaggle.json")
    record = WORK / "training" / f"{run_id}.json"
    code = run(
        [
            sys.executable,
            "-X",
            "utf8",
            "training/train_lora.py",
            "--config",
            str(path),
            "--record",
            str(record),
        ],
        "train",
        cwd=REPO,
    )
    for checkpoint in out.glob("checkpoint-*"):  # checksums are in the manifest
        shutil.rmtree(checkpoint)
    if code != 0:
        raise RuntimeError("training failed")


def evaluate() -> None:
    _, dtype = precision()
    adapter = REPO / "adapter"
    model_config = {
        "python": sys.executable,
        "model_dir": str(MODEL_DIR),
        "model_id": MODEL_ID,
        "model_revision": MODEL_REVISION,
        "adapter_dir": str(adapter) if JOB.get("adapter_id") else None,
        "adapter_id": JOB.get("adapter_id"),
        "adapter_sha256": JOB.get("adapter_sha256"),
        "adapter_config_sha256": JOB.get("adapter_config_sha256"),
        "device": "cuda",
        "dtype": dtype,
        "load_timeout_s": 600,
    }
    path = TMP / "model.kaggle.json"
    path.write_text(json.dumps(model_config, indent=2), encoding="utf-8")
    shutil.copy(path, LOGS / "model.kaggle.json")
    evaluation_id = JOB["evaluation_id"]
    command = [
        sys.executable,
        "-X",
        "utf8",
        "scripts/evaluate.py",
        "--split",
        JOB.get("split", "validation"),
        "--provider",
        "local",
        "--model-config",
        str(path),
        "--arms",
        JOB["arms"],
        "--output-dir",
        str(WORK / "evaluation"),
        "--evaluation-id",
        evaluation_id,
        "--gpu-memory",
    ]
    if JOB.get("case_ids"):
        command += ["--case-ids", *JOB["case_ids"]]
    if JOB.get("split") == "test":
        if STATUS.get("bundle", {}).get("git_dirty", True):
            raise RuntimeError("the test split needs a bundle built from a clean commit")
        command += ["--i-confirm-frozen-test", "--protocol-version", JOB["protocol_version"]]
    env = dict(os.environ, PYTHONPATH=str(REPO / "src"))
    code = run(command, "evaluate", cwd=REPO, env=env)
    records = WORK / "evaluation" / evaluation_id / "records.jsonl"
    if records.exists():
        run(
            [
                sys.executable,
                "-X",
                "utf8",
                "scripts/report_evaluation.py",
                str(records),
                "--out",
                str(WORK / "report" / evaluation_id),
            ],
            "report",
            cwd=REPO,
            env=env,
        )
    if code != 0:
        raise RuntimeError("evaluation failed")


def finish(ok: bool) -> None:
    STATUS["finished_at"] = datetime.now(UTC).isoformat(timespec="seconds")
    STATUS["ok"] = ok
    (WORK / "status.json").write_text(json.dumps(STATUS, indent=2), encoding="utf-8")
    files = {}
    for path in sorted(WORK.rglob("*")):
        if path.is_file() and path.name != "outputs-manifest.json":
            files[path.relative_to(WORK).as_posix()] = sha256_file(path)
    (WORK / "outputs-manifest.json").write_text(json.dumps(files, indent=2), encoding="utf-8")


def main() -> int:
    LOGS.mkdir(parents=True, exist_ok=True)
    TMP.mkdir(parents=True, exist_ok=True)
    ok = True
    try:
        if JOB.get("split", "validation") not in SPLITS:
            raise ValueError(f"unknown split {JOB.get('split')!r}")
        if JOB.get("split") == "test" and JOB.get("kind") != "eval":
            raise ValueError("only an evaluation job may read the test split")
        with Step("hardware"):
            STATUS["hardware"] = hardware()
            (WORK / "hardware.json").write_text(
                json.dumps(STATUS["hardware"], indent=2), encoding="utf-8"
            )
        with Step("bundle"):
            locate_bundle()
        with Step("install"):
            install()
        with Step("model"):
            download_model()
        if JOB["kind"] == "train":
            with Step("train"):
                train()
        else:
            with Step("evaluate"):
                evaluate()
    except Exception:  # every failure is recorded in status.json; the kernel then errors
        ok = False
    finish(ok)
    return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main())
